struct Mezon_Api_ParticipantInfo: Sendable {
  // SwiftProtobuf.Message conformance is added in an extension below. See the
  // `Message` and `Message+*Additions` files in the SwiftProtobuf library for
  // methods supported on all messages.

  var sid: String = String()

  var identity: String = String()

  var state: Mezon_Api_ParticipantInfo.State = .joining

  var isPublisher: Bool = false

  var kind: Mezon_Api_ParticipantInfo.Kind = .standard

  var unknownFields = SwiftProtobuf.UnknownStorage()

  enum State: SwiftProtobuf.Enum, Swift.CaseIterable {
    typealias RawValue = Int

    /// websocket' connected, but not offered yet
    case joining // = 0

    /// server received client offer
    case joined // = 1

    /// ICE connectivity established
    case active // = 2

    /// WS disconnected
    case disconnected // = 3
    case UNRECOGNIZED(Int)

    init() {
      self = .joining
    }

    init?(rawValue: Int) {
      switch rawValue {
      case 0: self = .joining
      case 1: self = .joined
      case 2: self = .active
      case 3: self = .disconnected
      default: self = .UNRECOGNIZED(rawValue)
      }
    }

    var rawValue: Int {
      switch self {
      case .joining: return 0
      case .joined: return 1
      case .active: return 2
      case .disconnected: return 3
      case .UNRECOGNIZED(let i): return i
      }
    }

    // The compiler won't synthesize support with the UNRECOGNIZED case.
    static let allCases: [Mezon_Api_ParticipantInfo.State] = [
      .joining,
      .joined,
      .active,
      .disconnected,
    ]

  }

  enum Kind: SwiftProtobuf.Enum, Swift.CaseIterable {
    typealias RawValue = Int

    /// standard participants, e.g. web clients
    case standard // = 0

    /// only ingests streams
    case ingress // = 1

    /// only consumes streams
    case egress // = 2

    /// SIP participants
    case sip // = 3

    /// LiveKit agents
    case agent // = 4

    /// Connectors participants
